sp_widget.client_script:
api.controller = function($scope, $location) {
    var c = this;

    c.approve = function(approval) {
        c.server.get({ action: 'approve', sys_id: approval.sys_id }).then(function(response) {
            c.data.pendingApprovals = response.data.pendingApprovals;
            c.data.approvedApprovals = response.data.approvedApprovals;
        });
    };

    c.reject = function(approval) {
        if (confirm('Are you sure you want to reject this approval?')) {
            c.server.get({ action: 'reject', sys_id: approval.sys_id }).then(function(response) {
                c.data.pendingApprovals = response.data.pendingApprovals;
                c.data.approvedApprovals = response.data.approvedApprovals;
            });
        }
    };

    c.goToAccount = function(approval) {
        var url = '?id=x_274351_finance_0_ach_page&account_sys_id=' + approval.accountSysId + '&amount=' + approval.amount + '&action_type=' + approval.type;
        $location.url(url);
    };
};

sp_widget.css:
.approvals-container {
    .panel-heading {
        background-color: #1a3a5c;
        color: #ffffff;
        .panel-title {
            font-size: 16px;
            font-weight: 600;
        }
    }
    .nav-tabs > li > a {
        color: #1a3a5c;
        font-weight: 600;
    }
    .nav-tabs > li.active > a,
    .nav-tabs > li.active > a:hover,
    .nav-tabs > li.active > a:focus {
        color: #1a3a5c;
        border-bottom: 2px solid #1a3a5c;
    }
    .badge {
        background-color: #1a3a5c;
    }
    .table > thead > tr > th {
        background-color: #f0f5fa;
        color: #1a3a5c;
        font-weight: 600;
        border-bottom: 2px solid #dce4ec;
    }
    .table > tbody > tr:hover {
        background-color: #f0f5fa;
    }
    .btn-sm {
        margin: 0 2px;
    }
    .empty-state {
        padding: 40px 0;
    }
    .tab-content {
        min-height: 200px;
    }
}

sp_widget.script:
(function() {
    data.pendingApprovals = [];
    data.approvedApprovals = [];

    // Handle approve/reject actions
    if (input && input.action) {
        if (input.action === 'approve') {
            var apprGr = new GlideRecord('sysapproval_approver');
            if (apprGr.get(input.sys_id)) {
                apprGr.setValue('state', 'approved');
                apprGr.update();
            }
        } else if (input.action === 'reject') {
            var rejGr = new GlideRecord('sysapproval_approver');
            if (rejGr.get(input.sys_id)) {
                rejGr.setValue('state', 'rejected');
                rejGr.update();
            }
        }
    }

    // Query pending approvals (state = 'requested')
    var pending = new GlideRecord('sysapproval_approver');
    pending.addQuery('approver', gs.getUserID());
    pending.addQuery('source_table', 'sc_req_item');
    pending.addQuery('state', 'requested');
    pending.setLimit(50);
    pending.query();
    while (pending.next()) {
        var ritm = new GlideRecord('sc_req_item');
        if (ritm.get(pending.getValue('sysapproval'))) {
            var catItemName = ritm.getDisplayValue('cat_item');
            var accountSysId = '';
            var accountDisplay = '';
            var amount = '';
            try {
                accountSysId = ritm.variables.account.toString();
                accountDisplay = ritm.variables.account.getDisplayValue();
                amount = ritm.variables.amount.toString();
            } catch (e) {
                // Variables may not exist on all RITMs
            }

            data.pendingApprovals.push({
                sys_id: pending.getUniqueValue(),
                ritm_number: ritm.getValue('number'),
                request_type: catItemName,
                requester: ritm.getDisplayValue('opened_by'),
                accountSysId: accountSysId,
                accountDisplay: accountDisplay,
                amount: amount,
                type: catItemName.toLowerCase().indexOf('deposit') >= 0 ? 'deposit' : 'withdrawal'
            });
        }
    }

    // Query approved approvals (state = 'approved')
    var approved = new GlideRecord('sysapproval_approver');
    approved.addQuery('approver', gs.getUserID());
    approved.addQuery('source_table', 'sc_req_item');
    approved.addQuery('state', 'approved');
    approved.setLimit(50);
    approved.query();
    while (approved.next()) {
        var ritm2 = new GlideRecord('sc_req_item');
        if (ritm2.get(approved.getValue('sysapproval'))) {
            var catItemName2 = ritm2.getDisplayValue('cat_item');
            var accountSysId2 = '';
            var accountDisplay2 = '';
            var amount2 = '';
            try {
                accountSysId2 = ritm2.variables.account.toString();
                accountDisplay2 = ritm2.variables.account.getDisplayValue();
                amount2 = ritm2.variables.amount.toString();
            } catch (e) {
                // Variables may not exist on all RITMs
            }

            data.approvedApprovals.push({
                sys_id: approved.getUniqueValue(),
                ritm_number: ritm2.getValue('number'),
                request_type: catItemName2,
                requester: ritm2.getDisplayValue('opened_by'),
                accountSysId: accountSysId2,
                accountDisplay: accountDisplay2,
                amount: amount2,
                type: catItemName2.toLowerCase().indexOf('deposit') >= 0 ? 'deposit' : 'withdrawal'
            });
        }
    }
})();
